void check(bool v,const char*m){if(!v)throw std::runtime_error(m);}
template<class T,class A>void shortBudgets(T&task,const kstation::FlashCredits&credits,unsigned&calls,uint64_t&checks,A&&advance){auto cost=task.nextClocks(credits);std::array<uint8_t,sizeof(T)>snapshot;std::memcpy(snapshot.data(),&task,sizeof(T));auto before=calls;for(unsigned budget=0;budget<cost;++budget){check(!advance(budget)&&calls==before&&!std::memcmp(snapshot.data(),&task,sizeof(T)),"Short budget mutated task/IO");++checks;}}
class Original final:public H8SEmulator{public:int readHistory()const{return lastread;}int writeHistory()const{return lastwrite;}int irqDepth()const{return indent;}void histories(int r,int w){lastread=r;lastwrite=w;}void irqDepth(int d){indent=d;}};
