 for(unsigned counter=0;counter<65536;counter+=257)for(unsigned flags:{0u,1u,0x7fu,0xffu}){f.prepare(0x8ba,flags);f.word(0xffff7c,counter);f.byte(0xfffd25,uint8_t(counter>>1));f.byte(0xfffd26,counter&255);f.byte(0xfffd24,uint8_t(counter>>2));f.byte(0xfffd27,uint8_t(counter));f.whole();}
