 for(unsigned mode:{0u,1u,2u,5u})for(unsigned direction:{1u,255u})for(unsigned parameter:{0u,1u})for(unsigned gate:{0u,1u}){f.prepare(0x3b6e,0xff);f.word(0xffff7c,0);f.byte(0xfffd24,direction);f.byte(0xfffd25,0);f.byte(0xfffd26,13);f.byte(0xfffd27,direction&128);f.byte(0xcd7c,mode);f.byte(0xcd7f,parameter);f.byte(0xbb0e,parameter);f.byte(0xcd70,gate?6:0);f.byte(0xcd72,2);f.whole();}
 uint64_t shorts=0,blocked=0;unsigned calls=0;kstation::FlashCredits cr;using E=kstation::UiEncoderTask;for(unsigned value:{0u,1u,127u,128u,255u}){E t;while(!t.complete()){auto advance=[&](unsigned b){return t.advanceBefore(b,cr,[&](E::Read r){++calls;return r==E::Read::Counter?0x8fffu:value;},[&](auto,auto){++calls;});};shortBudgets(t,cr,calls,shorts,advance);advance(t.nextClocks(cr));}}
 using U=kstation::UiEncoderRouteTask;for(unsigned mode:{0u,1u,2u,5u})for(unsigned delta:{0u,1u,255u})for(unsigned gate:{0u,1u}){U t;while(!t.complete()){if(t.awaiting()){check(!t.nextClocks(cr),"Encoder route gate");++blocked;t.resume(uint8_t(delta),uint8_t(gate));continue;}auto advance=[&](unsigned b){return t.advanceBefore(b,cr,[&](U::Read r){++calls;return r==U::Read::Mode?mode:gate;},[&](auto,auto){++calls;});};shortBudgets(t,cr,calls,shorts,advance);advance(t.nextClocks(cr));}}
